INSERT INTO `product` (`id`, `title`, `price`, `image`, `description`, `status`, `date`, `time`) VALUES
(5, 'Hospital Management Software', '12999', '3f6837ee195223ce90d7022c3f1d5f73_product.png', '<p><span style=\"color: rgb(77, 81, 86); font-family: Roboto, arial, sans-serif; letter-spacing: normal;\">The healthcare simulation field is rapidly evolving with new technologies & methodologies. One thing is constant: the urgent need for meaningful learning. Get a free consultation! Training In Motion. Contact Us. Cloud Simulation Platform. Types: Medical Schools, Nursing Schools, </span><span class=\"si130\" style=\"flex-shrink: 1; display: inline; overflow: hidden; text-transform: inherit; font-weight: 700; color: rgb(77, 81, 86); font-family: Roboto, arial, sans-serif; letter-spacing: normal;\">Hospital</span><span style=\"color: rgb(77, 81, 86); font-family: Roboto, arial, sans-serif; letter-spacing: normal;\"> Training, Emergency Medical.</span><br></p>', 'true', '2022-02-28', '02:18:11PM'),
(6, 'Pathology Software', '6999', '1646504477_blog.png', '<p><span style=\"color: rgb(77, 81, 86); font-family: arial, sans-serif; letter-spacing: normal;\">Pathology lab software lets you track, manage and automate laboratory operations. It also lets you generate invoices, manage inventories and stay on top of bill payments.</span><br></p>', 'true', '2022-03-05', '11:51:17PM'),
(7, 'Billing Software Developement', '4999', 'c8a8755da094f0359cb5e0ad8d6382c3_product.png', '<p><span style=\"color: rgb(77, 81, 86); font-family: Roboto, arial, sans-serif; letter-spacing: normal;\">Complete Restaurant Management Bundle for Fine-dine, QSR, Cloud kitchen, Cafe, Pub, Bakery. All-in-one POS&nbsp;</span><span class=\"si130\" style=\"flex-shrink: 0; display: inline; overflow: hidden; text-transform: inherit; font-weight: 700; color: rgb(77, 81, 86); font-family: Roboto, arial, sans-serif; letter-spacing: normal;\">software</span><span style=\"color: rgb(77, 81, 86); font-family: Roboto, arial, sans-serif; letter-spacing: normal;\">&nbsp;with added features to make your restaurant service more efficient. Trusted by 20,000+ Regional Language Support. Multiple&nbsp;</span><span class=\"si130\" style=\"flex-shrink: 1; display: inline; overflow: hidden; text-transform: inherit; font-weight: 700; color: rgb(77, 81, 86); font-family: Roboto, arial, sans-serif; letter-spacing: normal;\">Billing</span><span style=\"color: rgb(77, 81, 86); font-family: Roboto, arial, sans-serif; letter-spacing: normal;\">&nbsp;Stations. Cost Effective. Offices in 35+ Cities. 24/7 Support. API Available. GST-Ready. Services: Community Bazaar, Back-End, Advanced Products.</span><br></p>', 'true', '2022-02-26', '07:49:18PM'),
(8, 'Hostel Management Software', '4999', '1ec148874ddf1eff0dc3d04392be7916_product.png', '<div jsname=\"bVEB4e\" class=\"wWOJcd\" aria-controls=\"exacc__zcaYrGPAuCUseMPs5yMiAc4\" aria-expanded=\"true\" aria-labelledby=\"exacc__zcaYrGPAuCUseMPs5yMiAc3\" role=\"button\" tabindex=\"0\" jsaction=\"AWEk5c\" style=\"align-items: center; display: flex; max-height: none; min-height: 0px; position: relative; width: 652px; outline: 0px; color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: medium; letter-spacing: normal;\"><div jsname=\"jIA8B\" class=\"iDjcJe IX9Lgd wwB5gf\" id=\"exacc__zcaYrGPAuCUseMPs5yMiAc3\" style=\"-webkit-box-orient: vertical; color: inherit; display: -webkit-box; flex: 1 1 0%; -webkit-line-clamp: unset; margin: 12px 0px; overflow: hidden; font-size: 16px; transform: translate3d(0px, 0px, 0px);\">Which software is used in hostel management?</div><div jsname=\"Q8Kwad\" class=\"YsGUOb\" style=\"background-image: url(&quot;data:image/svg+xml,<svg focusable=\\&quot;false\\&quot; xmlns=\\&quot;http://www.w3.org/2000/svg\\&quot; viewBox=\\&quot;0 0 24 24\\&quot;><path fill=\\&quot;rgba(0,0,0,.54)\\&quot; d=\\&quot;M16.59 8.59L12 13.17 7.41 8.59 6 10l6 6 6-6z\\&quot;></path></svg>&quot;); display: inline-block; height: 24px; width: 24px; margin-top: -1px; transform: rotateZ(-180deg);\"></div><div jsname=\"K8Pnod\" class=\"r21Kzd\" data-hveid=\"CDEQAQ\" data-ved=\"2ahUKEwjxir2HyZ32AhVgSmwGHTMOA3EQuk56BAgxEAE\" style=\"height: 42px; left: 0px; position: absolute; top: 0px; width: 652px; visibility: hidden;\"></div></div><div jsname=\"rozPHf\" class=\"MBtdbb\" id=\"exacc__zcaYrGPAuCUseMPs5yMiAc4\" data-ved=\"2ahUKEwjxir2HyZ32AhVgSmwGHTMOA3EQ7NUEegQIMRAD\" style=\"position: absolute; width: 652px; color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: medium; letter-spacing: normal;\"><div class=\"ymu2Hb\" jsslot=\"\" style=\"position: relative;\"><div jsname=\"oQYOj\" class=\"t0bRye r2fjmd\" id=\"__zcaYrGPAuCUseMPs5yMiAc37\" data-hveid=\"CDEQBA\" data-ved=\"2ahUKEwjxir2HyZ32AhVgSmwGHTMOA3EQu04oAHoECDEQBA\" style=\"margin-bottom: 0px; margin-top: 0px; opacity: 1;\"><div id=\"WEB_ANSWERS_RESULT_6__zcaYrGPAuCUseMPs5yMiAc__32\"><div class=\"wDYxhc\" data-md=\"61\" style=\"clear: none;\"><div class=\"LGOjhe\" data-attrid=\"wa:/description\" aria-level=\"3\" role=\"heading\" data-hveid=\"CDAQAA\" style=\"overflow: hidden; padding-bottom: 20px;\"><span class=\"ILfuVd\" style=\"font-size: 16px; line-height: 24px;\"><span class=\"hgKElc\" style=\"padding: 0px 8px 0px 0px;\">A hostel management system was designed to provide a computerized process that is stress free, reliable and quick through the use of&nbsp;<b>PHP computer programming language</b>&nbsp;and MySQL database application to both the students and the staff in charge of the registration and hostel management processes</span></span></div></div></div></div></div></div>', 'true', '2022-02-26', '07:54:55PM'),
(9, 'Tiffin Services Management Software', '4999', 'ee740bc3a6fa87aa48da34fdcb57b448_product.jpg', '<p><span style=\"color: rgb(24, 24, 24); font-family: Heebo, Arial, Helvetica, sans-serif; font-size: 18px; letter-spacing: normal; text-align: center;\">We give you a hassle-free and convenient delivery system right at your doorstep. Automate your online tiffin operation &amp; let your client customize a schedule according to their needs.</span><br style=\"color: rgb(24, 24, 24); font-family: Heebo, Arial, Helvetica, sans-serif; font-size: 18px; letter-spacing: normal; text-align: center;\"><span style=\"color: rgb(24, 24, 24); font-family: Heebo, Arial, Helvetica, sans-serif; font-size: 18px; letter-spacing: normal; text-align: center;\">Tiffin / Mess service management and e-commerce software is a must for hassle free business operation.</span><br></p>', 'true', '2022-02-26', '07:57:53PM'),
(10, 'Real Estate Management Software', '10999', '1646504451_blog.jpg', '<p><span style=\"color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: 16px; letter-spacing: normal;\">Real Estate Management System (REMS) is </span><span style=\"color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: 16px; letter-spacing: normal;\"> starting from the management of the property, to the management of real estate agencies, agents, clients and financial transactions.</span><br></p>', 'true', '2022-03-05', '11:50:51PM'),
(11, 'Bricks Management Software', '12999', '1646504438_blog.jpg', '<p><span style=\"color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: 16px; letter-spacing: normal;\">Bricks is </span><b style=\"color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: 16px; letter-spacing: normal;\">an online project management software designed for architecture, engineering and construction</b><span style=\"color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: 16px; letter-spacing: normal;\"> (AEC) Most of these projects follow a traditional workflow of communication, such as long meetings.</span><br></p>', 'true', '2022-03-05', '11:50:38PM'),
(12, 'Online Quiz Competition Software', '7999', '1646504418_blog.jpg', '<p><span style=\"color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: 16px; letter-spacing: normal;\">Quiz Management System is an online application, from which </span><b style=\"color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: 16px; letter-spacing: normal;\">user can easily manage Academic details, Performance details</b><span style=\"color: rgb(32, 33, 36); font-family: arial, sans-serif; font-size: 16px; letter-spacing: normal;\">, Quiz details. Admin can track all the information of Academic, Score, Performance ect. Admin can edit, add, delete and update the records of Quiz, Participate, Winner.</span><br></p>', 'true', '2022-03-05', '11:50:18PM');
