INSERT INTO `review` (`id`, `name`, `position`, `message`, `image`, `status`, `date`, `time`) VALUES
(5, 'KARMASU IN', 'Client', 'DigiCoders Technologies is a great company in software development field, it has a complete resources to create website, mobile app or software. we are fully satisfied with the services they offered. I recommend DigiCoders.', '6f4c36a75b2de7d6ba2d92f1f7ec7553_review.jpg', 'true', '2022-03-11', '05:53:36PM'),
(6, 'AMAN KUMAR', 'Client', '\"Digicoders are the best institute of Lucknow\r\nand  best  teachers are provide lecture in class python, php ,.net, Mysql database technologies programming language\"', '355b2bf727a7fe83ce810a71dc68072d_review.jpg', 'false', '2022-03-11', '05:55:26PM'),
(7, 'saurabh yagyik', 'Client', '\"I feel very happy working at Indeed\r\nThe culture is very positive and transparent and everyone is open to new ideas and suggestions\r\nThere are lots of opportunities for growth at Indeed\r\nTeams at Indeed generally enjoy a lot of autonomy and freedom to choose what they want to work on......\"', '731bd968976d81b4950abafd20a0ff06_review.jpg', 'true', '2022-03-11', '05:56:08PM'),
(8, 'Avnish Tomar', 'Client', 'Digicoders is the excellent summer training company.. I\'m fully confident in web development', 'e1bf99c90d8abc4104a3efb22e4df17f_review.jpg', 'false', '2022-03-11', '05:56:36PM'),
(9, 'Saurabh Singh', 'Client', 'I will say one thing, if you want to make a website or mobile app in Lucknow, then you contact only  Digicoders Technologies', 'e5ef5a7d08943694721b47fdea28b4e2_review.jpg', 'true', '2022-03-11', '05:57:01PM'),
(10, 'Wisdom Adda', 'Client', 'Digicoders technologies company  is Best Software Development company in Lucknow.  My Project done is great.', '80d919d0c13fba35702ad0438ba4d839_review.jpg', 'true', '2022-03-11', '05:57:26PM'),
(11, 'abgupta007', 'Client', 'abgupta007	best website designing company in lucknow .this company developed a best of project. its develop a best website.it  is best best software development company.', '1d5934894add51b5ac99891525b2fd73_review.jpg', 'true', '2022-03-11', '05:58:28PM'),
(12, 'Abhishek Kumar', 'Client', 'Really it is very good company its sold goods and services at a reasonable price it will be very helpful for digital India.', 'ece919a568324b904425bca924acbf15_review.jpg', 'false', '2022-03-11', '05:59:04PM'),
(13, 'Ansh collction', 'Client', 'Digicoders technologies private is the best app development company..', '222bd0fda69a84520813f35d41e1cd8c_review.jpg', 'true', '2022-03-11', '05:59:31PM'),
(14, 'jagdeep gupta', 'Client', 'This is best platform to learn to web development and app development in the India and also this is best software company in the world', '15b815db2d402466bb5192d006d63ae7_review.jpg', 'false', '2022-03-11', '06:00:07PM'),
(15, 'Shikha Rajpoot', 'Client', '\"this is the best software devlopment company in uttar pradesh.\r\never employee is very well.and i think this is the best .\r\ni am very thankful Himanshu sir and Gopal sir... both person are  the best.and behavior is very friendly.....\r\n\r\nMEHANAT ITNI KHAMOSHI SE KARO KI KAMYABI SHOR MACHA DE.\r\nSUCCESS DOESN\'T JUST FIND YOU..\"', 'bc267d0571489e3bd1b75aa265fadac9_review.jpg', 'false', '2022-03-11', '06:00:29PM'),
(16, 'SHIVANI', 'Client', 'Digicoders Technologies is good IT company for students and employers too .', '8a2c872d5864586447dac5698feacfd7_review.jpg', 'true', '2022-03-11', '06:00:45PM'),
(17, 'Abhishek Kumar', 'Client', 'Digicoders technologies is the Awesome Company for Web and Software Development\"', '09c2c50e862bafb6250b6725940c5c67_review.jpg', 'true', '2022-03-11', '06:01:06PM'),
(18, 'Sudhanshu Kashyap', 'Client', 'This is the best software devlopment company in uttar pradesh.', '175786a022688057b2016d408bf76730_review.jpg', 'true', '2022-03-11', '06:01:53PM'),
(19, 'Euphoria Study Forum', 'Client', 'There is a good team, they have good knowledge of making website as well.', 'b6d03b3678b31e58ebb13e8fa4191cb4_review.jpg', 'true', '2022-03-11', '06:04:02PM'),
(20, 'Swati Pandey', 'Client', 'Digicoders technology is A best training center. I m Satified with  this  It provide better practical in presence of raw materials. The teachers of this company are very good specially himanshu Kashyap sir & Gopal Singh sir', 'c2afa9b9dc2585ab9d8328bd663bb95f_review.jpg', 'false', '2022-03-11', '06:04:29PM'),
(21, 'Ankita srivastava', 'Client', 'Team Digicoders professional website and Mobile apps development team', 'd2470c9de63fca53c89b0abba888f883_review.jpg', 'false', '2022-03-11', '06:05:00PM'),
(22, 'Satyam Maurya', 'Client', 'Digicoders technology  is  a best  and  better  in other technology  . Digicoders  technology  pvt.. ltd.popular at lucknow  And  best  training  center  IT .CSE. EC. branches And  it is also software company .teaching  style   is  very  friendly  with  students. Very impressed with  the digicoders  team knowlage  And  presentation', 'cd79beba347a834ddcc774fa5457a5a0_review.jpg', 'false', '2022-03-11', '06:05:19PM'),
(23, 'Bhawana Singh', 'Client', 'DigiCoders technology  is best IT company in Lucknow & best software development company. They also have amazing developers like Himanshu sir & Gopal sir.', '29e3bc9e082f09aac8407121cce2760b_review.jpg', 'false', '2022-03-11', '06:05:42PM'),
(24, 'Poonam Kumari', 'Client', '\"Digicoders Institute is best training Center yha ke best teachers Himanshu sir and gopal sir\r\nI am satisfied with this company\r\nAnd thanks all Institute group\r\nThank you sir.......\"', 'e1ce0752fe414f790d0c856f70a41fe7_review.jpg', 'false', '2022-03-11', '06:06:05PM'),
(25, 'Shaloo Singh', 'Client', '\"It\'s is a right platform for learning something new.\r\nDigicoders  provide us a platform to being a success software engineer\r\nin future.\r\nDigicoders is a platform to take a bright step for future and present.\"', '6b976f2593a44a13ba921d4b447e8e87_review.jpg', 'true', '2022-03-11', '06:06:44PM'),
(26, 'ANKIT SHARMA', 'Client', '\"DigiCoders Technologies Private Limited is a best Software development\r\nAnd Trainning company.I am also proud a apart of student in this comapny.\"', '35b8ca1ecfdb37d8d0dc5e246d098b7c_review.jpg', 'true', '2022-03-11', '06:07:12PM'),
(27, 'SWIKRITI SINGH', 'Client', 'thankful to gopal sir and himanshu sir ..to provide a friendly enviroment in our company..it is a best devlopment software comapny...both person are the best for software developing and teaching to CS ..', '684ef5189b8af9a7cc444ef7dd8796f0_review.jpg', 'false', '2022-03-11', '06:08:11PM'),
(28, 'Babita Yadav', 'Client', 'The best company is Digicoders. And best teacher is Mr. Himanshu Kashyap sir ji', '256fb4e2b644e5ee57cd5de852ae55f2_review.jpg', 'false', '2022-03-11', '06:08:31PM'),
(29, 'Pradeep Nishad', 'Client', 'For Learning programming and  coding  for fresher student of diploma , Betch(It, cs). DigiCoders  is a best it company in lucknow.', 'ac231cec490c3916f135b9d3128ebe3b_review.jpg', 'false', '2022-03-11', '06:08:50PM'),
(30, 'Avinash Chaurasiya', 'Client', 'digicoders is a best software company and training center. Digicoders work on many development and training platform.', '369f1c302cd35ab08b9c5ea4da97c4fe_review.jpg', 'true', '2022-03-11', '06:09:12PM'),
(31, 'Fresh Veg4u', 'Client', 'Team Digicoders Developed My application \"FreshVeg4u\" can order Grocery Materials..Shukriya digicoders lucknow ka', 'b45dd5a64b1e787cf3944c8686c1c649_review.jpg', 'true', '2022-03-11', '06:09:46PM'),
(32, 'Deepika Mishra', 'Client', '\"Traning is unique process of human developement  on that works to change\r\npersonal life for the better with the help of him/her achieve a number of specific objective....to be proud of student of digicoders technology........\r\nThankyou Digicoders technology\"', '3c62ade6ddfe14056d8f6310448dc7dc_review.jpg', 'true', '2022-03-11', '06:10:18PM'),
(33, 'Shreya Shukla', 'Client', '\"It is best IT company,where you can learn technologies like php, dot net and many more..soo if you wanna be master in coding\r\nDen you must go once there....\"', '5e605086ca29ca3a870b98bfa840601f_review.jpg', 'true', '2022-03-11', '06:10:42PM'),
